package com.hmdp.ai.runtime.tool;
import com.hmdp.ai.domain.model.*;import com.hmdp.ai.domain.run.*;import com.hmdp.ai.domain.security.*;import com.hmdp.ai.domain.tool.*;import org.junit.jupiter.api.Test;import java.time.Instant;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class ToolPermissionServiceTest {@Test void enforcesRequiredPermissionAndCriticalAdmin(){ToolPermissionService s=new ToolPermissionService();ExecutionContext run=context(EnumSet.of(AiPermission.AGENT_RUN));assertTrue(s.allowed(run,tool(ToolRiskLevel.LOW)));assertFalse(s.allowed(run,tool(ToolRiskLevel.CRITICAL)));assertTrue(s.allowed(context(EnumSet.of(AiPermission.ADMIN)),tool(ToolRiskLevel.CRITICAL)));}private ToolDefinition tool(ToolRiskLevel risk){return new ToolDefinition("t","v","code",1,"name",ToolProtocol.LOCAL_SKILL,"{}","{}",risk,false,true,1000,Collections.singletonList(AiPermission.AGENT_RUN),"{}",true);}private ExecutionContext context(Set<AiPermission>p){return new ExecutionContext("t","w","u","s",null,"r","a",1,"zh-CN","UTC",Collections.emptyList(),Collections.emptyList(),new AuthorizationContext(p),ExecutionBudget.defaults(),Instant.now().plusSeconds(30),Collections.emptyMap(),"trace");}}
